// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        c = new Owned();
        deployer = address(this);
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        if (c.owner() == deployer) {
            c.setOwner(address(0xdead));
            vm.assume(c.owner() != deployer);
        }

        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == deployer));
    }
}
